def eq(x,y): return x.shape==y.shape and np.array_equal(x,y)
pairs=[]
names={'A':A,'B':B,'C':C,'D':D,'E':E,'F':F,'G':G,'H':H,'I':I}
for n1,x in names.items():
    for n2,y in names.items():
        if n1>=n2: continue
        # check if x is a sub-block of y
        if x.shape[0]<=y.shape[0] and x.shape[1]<=y.shape[1]:
            for i in range(y.shape[0]-x.shape[0]+1):
                for j in range(y.shape[1]-x.shape[1]+1):
                    if np.array_equal(x, y[i:i+x.shape[0], j:j+x.shape[1]]):
                        pairs.append((n1,n2,i,j))
print(pairs)
